 42	    ) THEN
 43	        ALTER TABLE companion_graph_nodes ADD UNIQUE(user_id, node_id);
 44	    END IF;
 45	END $$;
 46	
 47	ALTER TABLE companion_graph_edges ADD COLUMN IF NOT EXISTS valid_from timestamptz NOT NULL DEFAULT clock_timestamp();
 48	ALTER TABLE companion_graph_edges ADD COLUMN IF NOT EXISTS recorded_at timestamptz NOT NULL DEFAULT clock_timestamp();
 49	ALTER TABLE companion_graph_edges ADD COLUMN IF NOT EXISTS embedding halfvec(1536);
 50	
 51	DO $$ DECLARE c record; BEGIN
 52	    FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='companion_graph_edges'::regclass AND contype='u' LOOP
 53	        EXECUTE format('ALTER TABLE companion_graph_edges DROP CONSTRAINT %I', c.conname);
 54	    END LOOP;
 55	END $$;
 56	
 57	CREATE UNIQUE INDEX IF NOT EXISTS companion_active_edge
 58	    ON companion_graph_edges(user_id, source_node_id, target_node_id, relationship_type, subject)
 59	    WHERE status='ACTIVE';
 60	
