 66	    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='edge_target_owner') THEN
 67	        ALTER TABLE companion_graph_edges ADD CONSTRAINT edge_target_owner
 68	            FOREIGN KEY(user_id, target_node_id) REFERENCES companion_graph_nodes(user_id,node_id);
 69	    END IF;
 70	    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='edge_episode_owner') THEN
 71	        ALTER TABLE companion_graph_edges ADD CONSTRAINT edge_episode_owner
 72	            FOREIGN KEY(user_id,source_episode_id) REFERENCES companion_episodes(user_id,episode_id);
 73	    END IF;
 74	    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chunk_episode_owner') THEN
 75	        ALTER TABLE companion_chunks ADD CONSTRAINT chunk_episode_owner
 76	            FOREIGN KEY(user_id,episode_id) REFERENCES companion_episodes(user_id,episode_id) ON DELETE CASCADE;
 77	    END IF;
 78	END $$;
 79	
 80	CREATE TABLE IF NOT EXISTS companion_fact_sources (
 81	    edge_id uuid REFERENCES companion_graph_edges(edge_id) ON DELETE CASCADE,
 82	    user_id text NOT NULL,
 83	    episode_id uuid NOT NULL,
 84	    PRIMARY KEY(edge_id,episode_id),
 85	    FOREIGN KEY(user_id,episode_id) REFERENCES companion_episodes(user_id,episode_id)
 86	);
 87	INSERT INTO companion_fact_sources
 88	SELECT edge_id,user_id,source_episode_id FROM companion_graph_edges
 89	WHERE source_episode_id IS NOT NULL
 90	ON CONFLICT DO NOTHING;
 91	
 92	CREATE INDEX IF NOT EXISTS companion_edge_owner ON companion_graph_edges(user_id,subject,status);
 93	CREATE INDEX IF NOT EXISTS companion_edge_embedding ON companion_graph_edges USING hnsw(embedding halfvec_cosine_ops);
 94	CREATE INDEX IF NOT EXISTS companion_node_embedding ON companion_graph_nodes USING hnsw(embedding halfvec_cosine_ops);
 95	CREATE INDEX IF NOT EXISTS companion_ephemeral_owner ON companion_ephemerals(user_id,expires_at);
 96	CREATE INDEX IF NOT EXISTS companion_chunk_owner ON companion_chunks(user_id);
 97	
 98	-- Preserve duplicate source rows before reconciling the current symbol projection on legacy volumes.
 99	CREATE TABLE IF NOT EXISTS migration_duplicate_symbols AS SELECT * FROM dev_code_symbols WHERE symbol_id IN (
100	    SELECT symbol_id FROM (
101	        SELECT symbol_id,row_number() OVER(
102	            PARTITION BY project_id,git_branch,file_path,symbol_name,symbol_type
103	            ORDER BY created_at DESC,symbol_id DESC
104	        ) AS rn FROM dev_code_symbols
105	    ) d WHERE rn>1
106	);
107	DELETE FROM dev_code_symbols WHERE symbol_id IN (SELECT symbol_id FROM migration_duplicate_symbols);
108	
109	DO $$ BEGIN
110	    IF NOT EXISTS (
111	        SELECT 1 FROM pg_constraint
112	        WHERE conrelid='dev_code_symbols'::regclass AND contype='u'
113	    ) THEN
114	        ALTER TABLE dev_code_symbols ADD UNIQUE(project_id,git_branch,file_path,symbol_name,symbol_type);
115	    END IF;
116	END $$;
117	
118	CREATE INDEX IF NOT EXISTS dev_scope ON dev_code_symbols(project_id,git_branch);
119	
120	UPDATE enterprise_documents SET status='ARCHIVED' WHERE doc_id IN (
121	    SELECT doc_id FROM (
122	        SELECT doc_id,row_number() OVER(
123	            PARTITION BY doc_title,allowed_role ORDER BY valid_from DESC,doc_id DESC
124	        ) AS rn FROM enterprise_documents WHERE status='ACTIVE'
125	    ) d WHERE rn>1
126	);
127	CREATE UNIQUE INDEX IF NOT EXISTS enterprise_active_document
128	    ON enterprise_documents(doc_title,allowed_role) WHERE status='ACTIVE';
129	
130	ALTER TABLE swarm_blackboard ADD COLUMN IF NOT EXISTS lease_token uuid;
131	ALTER TABLE swarm_blackboard ADD COLUMN IF NOT EXISTS lease_until timestamptz;
132	CREATE INDEX IF NOT EXISTS swarm_pending ON swarm_blackboard(workflow_id,status,created_at);
133	
134	DO $$ BEGIN
135	    IF NOT EXISTS (
136	        SELECT 1 FROM pg_constraint
137	        WHERE conrelid='task_trajectories'::regclass AND contype='c'
138	    ) THEN
139	        ALTER TABLE task_trajectories ADD CHECK(success_score BETWEEN 0 AND 1);
140	    END IF;
141	    IF NOT EXISTS (
142	        SELECT 1 FROM pg_constraint
143	        WHERE conrelid='tutor_user_progress'::regclass AND contype='c'
144	    ) THEN
145	        ALTER TABLE tutor_user_progress ADD CHECK(proficiency_score BETWEEN 0 AND 1);
146	    END IF;
147	END $$;
148	
149	ALTER TABLE enterprise_documents DROP COLUMN IF EXISTS tsv;
150	ALTER TABLE enterprise_documents ADD COLUMN tsv tsvector
151	    GENERATED ALWAYS AS(to_tsvector('english',doc_title || ' ' || content)) STORED;
152	CREATE INDEX IF NOT EXISTS idx_ent_doc_tsv ON enterprise_documents USING gin(tsv);

